// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: deep-green; icon-glyph: qrcode;

/**
 * Vietcombank QR home-screen widget for iPhone, run by the free Scriptable app.
 *
 * Shows the Vietcombank VietQR code on a white card, set on Vietcombank-style green artwork
 * (gradient, lime glow, emblem watermark, lime ribbon). All images come from the GitHub repo and
 * are cached on the phone, so the widget still works offline. Tapping it opens the QR
 * full-screen on the website.
 *
 * Sizes: small (QR + account), medium (details left, QR right), large (logo, big QR, details).
 * TEMPLATE: the site fills in __CARD_URL__, __HOLDER__, __NUMBER__ and __NUMBER_DISPLAY__ at build time
 * and serves the ready-to-paste script at <your secret card link>/widget.js. Don't put real values here:
 * this file is in a public repo. Setup steps: docs/SITE.md, "iPhone home-screen QR widget".
 */

// Your private contact card link (filled in by the site). Tapping the widget opens its payment QR.
const CARD_URL = "__CARD_URL__";
// Public artwork (background, logo) comes from the public GitHub repo so it loads even when the site
// is down. The QR is private: it is generated by the site under your secret card link.
const ASSET_BASE = "https://raw.githubusercontent.com/vutranquangminh/vutranquangminh/main/public";
const ACCOUNT = {
  holder: "__HOLDER__",
  number: "__NUMBER__",
  display: "__NUMBER_DISPLAY__",
};
const ASSETS = {
  // One QR per size: whole-pixel modules at 3x (no resampling) and a full 4-module white quiet zone.
  qr: (family) => `${CARD_URL}/widget/qr-${family}.png`,
  logo: "/assets/widget/vcb-logo-white.png",
  bg: (family) => `/assets/widget/vcb-bg-${family}.png`,
};

const WHITE = Color.white();
const LIME = new Color("#8dc63f");
const CARD = Color.white();

const fm = FileManager.local();
const cacheDir = fm.joinPath(fm.documentsDirectory(), "vcb-widget-cache");
if (!fm.fileExists(cacheDir)) fm.createDirectory(cacheDir, true);

/** Fetch an image from the site; fall back to the cached copy when offline. */
async function loadImage(path) {
  const url = path.startsWith("http") ? path : ASSET_BASE + path;
  const file = fm.joinPath(cacheDir, url.split("/").slice(-2).join("_"));
  try {
    const req = new Request(url);
    req.timeoutInterval = 10;
    const img = await req.loadImage();
    fm.writeImage(file, img);
    return img;
  } catch {
    return fm.fileExists(file) ? fm.readImage(file) : null;
  }
}

function mono(size) {
  // Monospaced system fonts arrived in later Scriptable versions; fall back gracefully.
  return typeof Font.boldMonospacedSystemFont === "function" ? Font.boldMonospacedSystemFont(size) : Font.boldSystemFont(size);
}

function text(stack, value, font, color = WHITE, opacity = 1) {
  const t = stack.addText(value);
  t.font = font;
  t.textColor = color;
  t.textOpacity = opacity;
  t.lineLimit = 1;
  t.minimumScaleFactor = 0.6;
  return t;
}


/**
 * White rounded card holding the QR. QR codes need dark modules on a light background with a white
 * margin around them; the image already includes that margin, the card adds a little more.
 */
function qrCard(parent, qr, family, radius) {
  // The image's pixel width / 3, so iOS draws it 1:1 on 3x screens (fallback sizes before it loads).
  const qrPoints = qr ? qr.size.width / 3 : { small: 109, medium: 123, large: 191 }[family];
  const card = parent.addStack();
  card.size = new Size(qrPoints + 6, qrPoints + 6);
  card.backgroundColor = CARD;
  card.cornerRadius = radius;
  card.centerAlignContent();
  if (qr) {
    const img = card.addImage(qr);
    img.imageSize = new Size(qrPoints, qrPoints);
  } else {
    const t = text(card, "Open Scriptable once online", Font.semiboldSystemFont(10), new Color("#00592f"));
    t.centerAlignText();
  }
  return card;
}

function addLogo(parent, logo, width) {
  if (!logo) return text(parent, "Vietcombank", Font.heavySystemFont(width / 7));
  const img = parent.addImage(logo);
  img.imageSize = new Size(width, (width * logo.size.height) / logo.size.width);
  return img;
}

function small(widget, { qr }) {
  widget.setPadding(10, 10, 10, 10);
  const top = widget.addStack();
  top.addSpacer();
  qrCard(top, qr, "small", 14);
  top.addSpacer();
  widget.addSpacer(6);
  const bottom = widget.addStack();
  bottom.addSpacer();
  text(bottom, ACCOUNT.display, mono(11));
  bottom.addSpacer();
}

function medium(widget, { qr, logo }) {
  widget.setPadding(14, 16, 14, 14);
  const row = widget.addStack();
  row.layoutHorizontally();
  row.centerAlignContent();

  // Details on the left, QR on the right.
  const info = row.addStack();
  info.layoutVertically();
  info.size = new Size(0, 130);
  addLogo(info, logo, 132);
  info.addSpacer();
  text(info, "SCAN TO PAY", Font.heavySystemFont(9), LIME);
  info.addSpacer(3);
  text(info, ACCOUNT.display, mono(18));
  info.addSpacer(2);
  text(info, ACCOUNT.holder, Font.semiboldSystemFont(10), WHITE, 0.82);

  row.addSpacer();
  qrCard(row, qr, "medium", 16);
}

function large(widget, { qr, logo }) {
  widget.setPadding(18, 18, 18, 18);
  const head = widget.addStack();
  head.addSpacer();
  addLogo(head, logo, 150);
  head.addSpacer();

  widget.addSpacer();
  const middle = widget.addStack();
  middle.addSpacer();
  qrCard(middle, qr, "large", 20);
  middle.addSpacer();
  widget.addSpacer();

  for (const [value, font, color, opacity] of [
    ["SCAN TO PAY", Font.heavySystemFont(10), LIME, 1],
    [ACCOUNT.display, mono(24), WHITE, 1],
    [ACCOUNT.holder, Font.semiboldSystemFont(12), WHITE, 0.82],
  ]) {
    const line = widget.addStack();
    line.addSpacer();
    text(line, value, font, color, opacity);
    line.addSpacer();
    widget.addSpacer(2);
  }
}

async function buildWidget(family) {
  const [qr, logo, bg] = await Promise.all([loadImage(ASSETS.qr(family)), loadImage(ASSETS.logo), loadImage(ASSETS.bg(family))]);
  const widget = new ListWidget();
  widget.backgroundColor = new Color("#00632f");
  if (bg) widget.backgroundImage = bg;
  widget.url = `${CARD_URL}?pay=vcb`;
  // Re-download once a day so changes on the website reach the widget.
  widget.refreshAfterDate = new Date(Date.now() + 24 * 60 * 60 * 1000);

  const parts = { qr, logo };
  if (family === "large") large(widget, parts);
  else if (family === "medium") medium(widget, parts);
  else small(widget, parts);
  return widget;
}

const family = ["small", "medium", "large"].includes(config.widgetFamily) ? config.widgetFamily : "medium";

if (config.runsInWidget) {
  Script.setWidget(await buildWidget(family));
} else {
  // Running inside the app caches every size's artwork for offline use, then previews the medium widget.
  for (const size of ["small", "large"]) await Promise.all([loadImage(ASSETS.bg(size)), loadImage(ASSETS.qr(size))]);
  await (await buildWidget("medium")).presentMedium();
}
Script.complete();
